public class Warm {
    static int f(int x) { return x * 2 + 1; }

    public static void main(String[] a) {
        long t = System.nanoTime();
        long s = 0;
        for (int i = 0; i < 50_000_000; i++) s += f(i);
        long ms = (System.nanoTime() - t) / 1_000_000;
        System.out.println(s + " in " + ms + " ms");
    }
}
