import java.util.Arrays;

public class ArrayRealTimeDemo {

    public static void main(String[] args) {

        // Real time: PVR seat map, 4 rows and 6 seats each
        boolean[][] booked = new boolean[4][6];
        String[] rowNames = {"A", "B", "C", "D"};

        // book a few seats
