static final Map<Integer, Long> memo = new HashMap<>();
static long fib(int n) {
    if (n < 2) return n;
    Long cached = memo.get(n);
    if (cached != null) return cached;
    long v = fib(n - 1) + fib(n - 2);   // each n is computed only once
    memo.put(n, v);
    return v;
}
