        return n * n;
    }
}

class Circle {
    Operation op; // aggregation - Circle HAS-A Operation
    double pi = 3.14;

    double area(int radius) {
        op = new Operation();
        int rsquare = op.square(radius); // delegates the calculation
        return pi * rsquare;
    }

    public static void main(String[] args) {
        Circle c = new Circle();
        System.out.println(c.area(5));
    }
}
