            Thread.sleep(100); // UPI verification, no shared data touched
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public int totalBookings() {
        synchronized (seatLock) {
            return bookings.size();
        }
    }
}

