// A lazy hash is a benign race: every thread computes the same value
final class Lazy {
    private final String raw;
    private int hash;
    Lazy(String r) { raw = r; }
    @Override public int hashCode() {
        int h = hash;
        if (h == 0) hash = h = raw.hashCode();
        return h;
    }
}

