@FunctionalInterface interface Retry<T> { T call() throws Exception; }
static <T> T withRetry(Retry<T> action, int times) throws Exception {
    Exception last = null;
    for (int i = 0; i < times; i++) {
        try { return action.call(); }
        catch (Exception e) { last = e; }
    }
    throw last;
}
