            case "TUESDAY":
            case "WEDNESDAY":
            case "THURSDAY":
            case "FRIDAY":
                type1 = "Weekday";
                break;
            case "SATURDAY":
            case "SUNDAY":
                type1 = "Weekend";
                break;
            default:
                type1 = "Unknown";
        }

