static long sumRecursive(int n) { return n == 0 ? 0 : n + sumRecursive(n - 1); }

static long sumLoop(int n) {
    Deque<Integer> st = new ArrayDeque<>();
    for (int i = 1; i <= n; i++) st.push(i);
    long s = 0;
    while (!st.isEmpty()) s += st.pop();
    return s;
}
