// before: a new formatter and many Strings per call
String slow(List<Integer> ids) {
    String s = "";
    for (int id : ids) s += id + ",";
    return s;
}
// after: one builder
String fast(List<Integer> ids) {
    StringBuilder sb = new StringBuilder(ids.size() * 4);
    for (int id : ids) sb.append(id).append(',');
    return sb.toString();
}

