static void dfs(Node root) {
    Deque<Node> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Node n = stack.pop();
        visit(n);
        for (Node c : n.children()) stack.push(c);   // no recursion, no overflow
    }
}

